%The second item deserves some explanations. It essentially says that for two distributions $\mu$ and $\nu$ to be bisimilar, they must have the same probability of enabling any given action.    
%Furthermore, conditioning on that action $a$ is being taken, 
%any actual $a$-move of $\mu$ must be matched by a corresponding $a$-move of $\nu$. When we write $\TRANA{\mu|_a}{a}{\mu'}$,
%we assume that $\mu(a)>0$ implicitly.
Obviously, the bisimilarity $\sim^\A$ is the largest bisimulation relation. 

For probabilistic automata which are not input enabled, we define distribution-based bisimulation with the help of
\emph{input enabled extension} specified as follows.

\begin{definition}
Let $\A=(S, Act, \rightarrow,L,\alpha)$ be a probabilistic automaton over $AP$.
The \emph{input enabled extension} of $\A$, denoted by $\A_\bot$, is defined as
an (input enabled) probabilistic automaton $(S_\bot, Act, \rightarrow^\bot, L_\bot, \alpha)$ over $AP_\bot$ where
\begin{enumerate}
\item  $S_\bot = S\cup \{\bot\}$ where $\bot$ is a \emph{dead} state
not in $S$;
\item $AP_\bot=AP\cup \{dead\}$ with $dead\not\in AP$;
\item $\rightarrow^\bot {=} \rightarrow \cup~ \{(s, a, \dirac{\bot}) \mid a\not \in Act(s)\} \cup \{(\bot, a, \dirac{\bot}) \mid a \in Act\}$;
\item $L_\bot(s) = L(s)$ for any $s\in S$, and $L_\bot(\bot)=\{dead\}$.
\end{enumerate} 
\end{definition}

\begin{definition}
  Let $\A$ be a probabilistic automaton which is not input enabled. Then 
  $\mu$ and $\nu$ are bisimilar, denoted by $\mu\sim^\A\nu$, 
  if $\mu\sim^{\A_\bot}\nu$ in $\A_\bot$.
\end{definition}

We always omit the superscript $\A$ in $\sim^\A$ when no confusion arises. 


\subsection{Compatibility}\label{sec:compatibility}
In this section we instantiate appropriate labeling functions and show
that our notion of bisimilarity is a conservative extension of both
probabilistic bisimulation~\cite{Rabin63} 
and equivalence relations~\cite{DoyenHR08}.

\begin{lemma}\label{lem:bsp}
 Let $\A$ be a probabilistic automaton where $AP=Act$, and $L(s) =Act(s)$ for each $s$. Then, $\mu\BSP \nu$ implies
 $\mu \sim \nu$.
\end{lemma}
\begin{proof}
First, it is easy to see that for a given probabilistic automata $\A$ with $AP=Act$ and $L(s) =Act(s)$ for each $s$, and distributions $\mu$ and $\nu$ in $\dist(S)$, 
$\mu \BSP\nu$ in $\A$ if and only if $\mu \BSP\nu$ in the input enabled extension $\A_\bot$. Thus 
we can assume without loss of any generality that $\A$ itself is input enabled. 

It suffices to show that the symmetric relation
$$R = \{ (\mu, \nu) \mid \mu \BSP\nu \}$$
is a bisimulation. For each $A\subseteq Act$, let $S(A) = \{s\in S \mid  L(s)= A\}$. Then $S(A)$ is the disjoint union of some equivalence classes of $\BSP$; that is, $S(A) = \dotcup\{M\in S/{\BSP} \mid M\cap S(A) \neq \emptyset\}$. Suppose $\mu\BSP\nu$. Then for any $M\in S/{\BSP}$, $\mu(M) = \nu(M)$, hence $\mu(A) = \mu(S(A)) = \nu(S(A)) = \nu(A).$ 

Let $\TRANA{\mu}{a}{\mu'}$. Then for any $s\in S$ there exists $\TRANPA{s}{a}{\mu_s}$ such that
$$\mu' = \sum_{s\in S} \mu(s)\cdot \mu_s.$$
Now for each $t\in S$, let $[t]_{\BSP}$ be the equivalence class of $\BSP$ which contains $t$. Then for every $s \in [t]_{\BSP}$, to match the transition $\TRANPA{s}{a}{\mu_s}$ there exists some $\nu_t^s$ such that $\TRANPA{t}{a}{\nu^s_t}$ and $\mu_s\BSP \nu^s_t$. Let 
$$\nu_t = \sum_{s\in [t]_{\BSP}}\frac{\mu(s)}{\mu([t]_{\BSP})}\cdot \nu_t^s.$$
Then we have $\TRANPA{t}{a}{\nu_t}$, and $\TRANA{\nu}{a}{\nu'}$ where 
$$\nu' := \sum_{t\in S} \nu(t) \cdot\nu_t.$$
It remains to prove $\mu' \BSP \nu'$. For any $M\in S/{\BSP}$, since $\mu_s\BSP \nu^s_t$ we have 
\begin{eqnarray*}
\nu_t(M) &=& \sum_{s\in [t]_{\BSP}}\frac{\mu(s)}{\mu([t]_{\BSP})} \nu_t^s(M)= \sum_{s\in [t]_{\BSP}}\frac{\mu(s)}{\mu([t]_{\BSP})} \mu_s(M).
\end{eqnarray*} 
Thus
\begin{eqnarray*}
\nu'(M) &=&  \sum_{t\in S} \nu(t) \sum_{s\in [t]_{\BSP}}\frac{\mu(s)}{\mu([t]_{\BSP})} \mu_s(M)\\
&=& \sum_{s\in S}  \mu(s)\mu_s(M)\sum_{t\in [s]_{\BSP}}\frac{\nu(t)}{\nu([s]_{\BSP})}\\
&=& \sum_{s\in S} \mu(s) \mu_s(M)  = \mu'(M)
\end{eqnarray*} 
where for the second equality we have used the fact that $\mu([t]_{\BSP}) = \nu([s]_{\BSP})$ for any $s\BSP t$. \qed
\end{proof}


Probabilistic bisimulation is defined over states inside one
automaton, whereas equivalence and distribution for reactive automata are
defined over two automata. However, they can be connected by the notion of
direct sum of two automata, which is the automaton obtained by
considering the disjoint union of states, edges and labeling functions
respectively.

\begin{lemma}\label{lem:eqra}
  Let $\A_1$ and $\A_2$ be two reactive automata with the same set of
  actions $Act$. Let $F_i=\{s\in S_i \mid L(s)=AP\}$. Then, the following are equivalent:
  \begin{enumerate}
  \item $\A_1$ and
  $\A_2$ are equivalent,
\item $\alpha_1\sim_d\alpha_2$, 
\item $\alpha_1\sim \alpha_2$ in their direct sum. 
  \end{enumerate}
\end{lemma}
\begin{proof}
  The equivalence between (1) and (2) is shown in~\cite{DoyenHR08}. 
  The equivalence between (2) and (3) is straightforward, as for
  reactive automata our definition degenerates to Definition \ref{def:distribution_based}. \qed
\end{proof}

