\subsection{Properties of the Relations}\label{sec:property}
In the following, we show that the notion of bisimilarity is in harmony with the linear combination and the limit of distributions. 

\begin{definition}\label{def:decom}
 A binary relation $R \subseteq
  \dist(S) \times\dist(S)$
 is said to be 
 \begin{itemize}
 \item \emph{linear}, if for any finite set $I$ and any probabilistic distribution $\{p_i\}_{i\in I}$, $\mu_i R \nu_i$ for each $i$
 implies
 $(\sum_{i\in I}p_i\cdot\mu_i)R(\sum_{i\in I}p_i\cdot\nu_i)$;
 \item \emph{continuous}, if for any convergent sequences of distributions $\{\mu_i\}_i$ and $\{\nu_i\}_i$, $\mu_i R \nu_i$ for each $i$ implies $(\lim_i \mu_i) R (\lim_i\nu_i)$;
 \item \emph{left-decomposable}, if
 $(\sum_{i\in I}p_i\cdot\mu_i)R\nu$, where $0< p_i \leq 1$ and $\sum_{i\in I}p_i = 1$, then $\nu$ can be written as $\sum_{i\in I}p_i\cdot\nu_i$
    such that $\mu_i R\nu_i$ for every $i \in I$.
\item \emph{left-convergent}, if
 $(\lim_i \mu_i)R\nu$, then for any $i$ we have $\mu_i R\nu_i$ for some $\nu_i$ with $\lim_i \nu_i = \nu$.
\end{itemize}
\end{definition}

We prove below that our transition relation between distributions satisfies these properties.

\begin{lemma}\label{lem:tranld} For an input enabled probabilistic automata, the transition relation $\TRANA{}{a}{}$ between distributions is linear, continuous, left-decomposable,
and left-convergent.
\end{lemma}
\begin{proof}
 \begin{itemize}
 \item \emph{Linearity}. Let $I$ be a finite index set and $\{p_i\mid i\in I\}$ a probabilistic distribution on $I$. 
Suppose $\TRANA{\mu_i}{a}{\nu_i}$ for each $i \in I$.  Then by definition, for each
   $s$ there exists
   $\TRANPA{s}{a}{\mu^i_s}$ such that 
   $\nu_i=\sum_{s}\mu_i(s)\cdot\mu^i_s$.
Now let $\mu=\sum_{i\in I}p_i\cdot\mu_i$. Then for each $s\in \supp(\mu)$,
$$\TRANPA{s}{a}\mu_s:=\sum_{i\in I}{\frac{p_i\mu_i(s)}{\mu(s)}\cdot \mu^i_s}.$$
 On the other hand, we check that 
\begin{eqnarray*}\nu := \sum_{i\in I} p_i \cdot \nu_i &=& 
\sum\limits_{s\in S}\sum_{i\in I} p_i\mu_i(s)\cdot\mu^i_s = \sum\limits_{s\in S }\mu(s)\cdot\mu_s .
\end{eqnarray*}
 Thus $\TRANA{\mu}{a}{\nu}$ as expected.

\item \emph{Continuity}. Suppose $\TRANA{\mu_i}{a}{\nu_i}$ for each $i \in I$, and $\lim_i \mu_i = \mu$.  By definition, for each
   $s$ there exists
   $\TRANPA{s}{a}{\mu^i_s}$ such that 
   $\nu_i=\sum_{s}\mu_i(s)\cdot\mu^i_s$.
Note that $\dist(S)$ is a compact set. For each $s$ we can choose a convergent subsequence $\{\mu_s^{i_k}\}_k$ of $\{\mu_s^{i}\}_i$ such that
$\lim_k \mu_s^{i_k} = \mu_s$ for some $\mu_s$. Then $\TRANPA{s}{a}{\mu_s}$, and 
\begin{eqnarray*}\TRANA{\mu}{a}{\nu} :=  \sum_{s\in S}\mu(s)\cdot\mu_s.
\end{eqnarray*}
Note that for each $k$,
 \begin{eqnarray*} \|\nu_{i_k} - \nu\|_1 &\leq & \|\mu_{i_k} - \mu\|_1 + \sum\limits_{s\in S} \mu(s) \|\mu^{i_k}_s - \mu_s\|_1
\end{eqnarray*}
where $\|\cdot\|_1$ denotes the $l_1$-norm.
We have $\nu=\lim_k\nu_{i_k}$ by the assumption that $\lim_i \mu_i = \mu$. 
Thus $\lim_i \nu_i = \nu$, as $\{\nu_i\}_i$ itself converges.

 \item \emph{Left-decomposability}. Let
 $\mu:=\TRANA{(\sum_{i\in I}p_i\cdot\mu_i)}{a}{\nu}$. Then by definition, for each
   $s$ there exists
   $\TRANPA{s}{a}{\mu_s}$ such that 
   $\nu=\sum_{s}\mu(s)\cdot\mu_s$. Thus 
$$\TRANA{\mu_i}{a}\nu_i:=\sum\limits_{s\in S }\mu_i(s)\cdot\mu_s.$$
Finally, it is easy to show that $\sum_{i\in I} p_i \cdot \nu_i = \nu$.  

 \item \emph{Left-convergence}. Similar to the last case.   \qed
\end{itemize}
\end{proof}
