\section{Bisimulation Metrics}\label{sec:metric}
We present distribution-based bisimulation metrics with discounting factor $\gamma\in (0,1]$ in
this section.  Three different ways of defining bisimulation
metrics between states exist in the literature: one coinductive
definition based on bisimulations~\cite{YingW00,Ying01,Ying02,DesharnaisLT08}, one based on
the maximal logical differences~\cite{DesharnaisGJP99,DesharnaisGJP04,BreugelSW07},
and one on fixed point~\cite{AlfaroMRS07,BreugelSW07,FernsPP11}. We propose all the three
versions for our distribution-based bisimulations with discounting. Moreover, we show that they coincide.  We fix a discount
factor $\gamma\in (0,1]$ throughout this section. For any $\mu, \nu\in \dist(S)$, we define the distance
$$d_{AP}(\mu, \nu) := \frac 12 \sum_{A\subseteq AP} \left|\mu(A) - \nu(A)\right|.$$
Then it is easy to check that $$d_{AP}(\mu, \nu) = \max_{\B\subseteq 2^{AP}} \left|\sum_{A\in \B} \mu(A) - \sum_{A\in \B} \nu(A)\right|= \max_{\B\subseteq 2^{AP}} \left[\sum_{A\in \B} \mu(A) - \sum_{A\in \B} \nu(A)\right].$$
\subsection{A Direct Approach}

\begin{definition}
Let $\A=(S, Act, \rightarrow,L,\alpha)$ be an input enabled probabilistic automaton.  A family of symmetric relations $\{R_\epsilon \mid \epsilon \geq 0\}$ over $\dist(S)$ is a (discounted) approximate bisimulation if
for any $\epsilon\geq 0$ and $\mu R_\epsilon\nu$, we have 
  \begin{enumerate}
%\item  for each $A\subseteq AP$, $|\mu(A)-\nu(A)| \leq \epsilon$;
\item $d_{AP}(\mu, \nu)\leq \epsilon$;
\item 
for each $a\in Act$,  $\TRANA{\mu}{a}{\mu'}$ implies that there exists a transition
  $\TRANA{\nu}{a}{\nu'}$ such that $\mu' R_{\epsilon/\gamma}\nu'$.
\end{enumerate}
We write $\mu\sim_\epsilon^\A\nu$ whenever there is an approximate
 bisimulation $\{R_\epsilon \mid \epsilon\geq 0\}$ such that $\mu R_\epsilon \nu$.  For any two
distributions $\mu$ and $\nu$, we define the bisimulation distance
of $\mu$ and $\nu$ as

\begin{equation}\label{def:metric}
D_b^\A(\mu, \nu) = \inf\{\epsilon \geq 0 \mid \mu\sim^\A_{\epsilon} \nu\}.
\end{equation}
\end{definition}

Again, the approximate bisimulation and bisimulation distance of distributions in a general probabilistic automaton can be
defined in terms of the corresponding notions in the input enabled extension; that is, $\mu\sim_\epsilon^\A\nu$ if $\mu\sim_\epsilon^{\A_\bot}\nu$, and $D_b^\A(\mu, \nu) := D_b^{\A_\bot}(\mu, \nu)$. We always omit the superscripts for simplicity if no confusion arises.

It is standard to show that the family $\{\sim_\epsilon \mid \epsilon\geq 0\}$ is itself an approximate bisimulation.
The following lemma collects some more properties of $\sim_\epsilon$.

\begin{lemma}\label{lem:abis}
\begin{enumerate}
\item For each $\epsilon$, the $\epsilon$-bisimilarity $\sim_\epsilon$ is both
linear and continuous. 
%\item
%If $R_{i}$ is an $\epsilon_{i}$-bisimulation ($i=1,2$), then $R_{1}\circ R_{2}$ is an $(\epsilon_{1} + \epsilon_{2})$-bisimulation;
\item If $\mu\sim_{\epsilon_1}\nu$ and $\nu\sim_{\epsilon_2}\omega$, then $\mu\sim_{\epsilon_1+\epsilon_2}\omega$;
\item $\sim_{\epsilon_1}{\subseteq}\sim_{\epsilon_2}$ whenever $\epsilon_{1}\leq \epsilon_{2}$.
\end{enumerate}
\end{lemma}
\begin{proof} 
The proof of item 1 is similar to
Theorem~\ref{thm:ld}.
For item 2, it suffices to show that $\{R_\epsilon \mid \epsilon\geq 0\}$ where $R_\epsilon\ {=} \bigcup_{\epsilon_1+\epsilon_2 = \epsilon}\left(\sim_{\epsilon_1}\circ\sim_{\epsilon_2}\right)$ is an approximate bisimulation (in the extended automata, if necessary), which is routine. For item 3, suppose $\epsilon_2>0$. Then it is  easy to show $\{R_\epsilon \mid \epsilon\geq 0\}$,  $R_\epsilon\ {=} \sim_{\epsilon\epsilon_1/\epsilon_2}$, is an approximate bisimulation. 
Now if  $\mu\sim_{\epsilon_1}\nu$, that is, $\mu\sim_{\epsilon_2\epsilon_1/\epsilon_2}\nu$, then $\mu R_{\epsilon_2}\nu$, and thus $\mu\sim_{\epsilon_2}\nu$ as required. \qed
\end{proof}

The following theorem states that the infimum in the definition
Eq.~\eqref{def:metric} of bisimulation distance can be replaced by
minimum; that is, the infimum is achievable.
\begin{theorem}\label{thm:metric}
For any $\mu,\nu\in \dist(S)$,  $\mu\sim_{D_b(\mu,\nu)} \nu.$
\end{theorem}
\begin{proof} By definition, we need to prove $\mu\sim_{D_b(\mu,\nu)} \nu$ in the extended automaton. We first prove that for any $\epsilon\geq0$, the symmetric relations $\{R_\epsilon \mid \epsilon \geq 0\}$ where 
\begin{eqnarray*}
R_\epsilon=\{(\mu, \nu)& \mid &\mu \sim_{\epsilon_{i}} \nu \mbox{ for each } \epsilon_{1}\geq\epsilon_{2}\geq\cdots \geq 0, \mbox{ and } \lim_{i\rightarrow \infty} \epsilon_{i}=\epsilon\}
\end{eqnarray*}
is an approximate bisimulation. Suppose $\mu R_\epsilon\nu$. Since $\mu\sim_{\epsilon_{i}} \nu$ we have $d_{AP}(\mu, \nu)\leq \epsilon_i$ for each $i$. Thus $d_{AP}(\mu, \nu)\leq \epsilon$ as well. 
Furthermore, if $\TRANA{\mu}{a}{\mu'}$, then for any $i\geq 1$,  $\TRANA{\nu}{a}{\nu_{i}}$ and
$\mu'\sim_{\epsilon_{i}/\gamma}\nu_{i}$. Since $\dist(S)$ is compact, there exists a subsequence $\{\nu_{i_k}\}_k$ of $\{\nu_i\}_i$ such that $\lim_k \nu_{i_k} = \nu'$ for some $\nu'$. We claim that
\begin{itemize}
\item $\TRANA{\nu}{a}{\nu'}$. This follows from the continuity of the transition $\TRANA{}{a}{}$, Lemma~\ref{lem:tranld}.
\item For each $k\geq 1$,  $\mu'\sim_{\epsilon_{i_k}/\gamma}\nu'$. Suppose conversely that $\mu'\not\sim_{\epsilon_{i_k}/\gamma}\nu'$ for some $k$. Then by the continuity of $\sim_{\epsilon_{i_k}/\gamma}$, we have $\mu'\not\sim_{\epsilon_{i_k}/\gamma}\nu_j$ for some $j\geq i_k$. This contradicts the fact that  $\mu'\sim_{\epsilon_j/\gamma}\nu_{j}$ and Lemma~\ref{lem:abis}(3). Thus $\mu' R_{\epsilon/\gamma}\nu'$ as required.
\end{itemize}

Finally, it is direct from definition that there exists a decreasing sequence $\{\epsilon_i\}_i$ such that $\lim_i \epsilon_i = D_b(\mu, \nu)$ and $\mu \sim_{\epsilon_{i}} \nu$ for each $i$. Then the theorem follows.
\qed
\end{proof}

A direct consequence of the above theorem is that the bisimulation distance between two distributions vanishes if and only if they are  bisimilar.
\begin{corollary} For any $\mu, \nu\in \dist(S)$, $\mu\sim \nu$ if and only if $D_b(\mu,\nu)=0$. \end{corollary}
\begin{proof} Direct from Theorem~\ref{thm:metric}, by noting that $\sim{=}\sim_{0}$. \qed\end{proof}

The next theorem shows that $D_b$ is indeed a pseudometric.
\begin{theorem}
The bisimulation distance $D_b$ is a pseudometric on $\dist(S)$.
\end{theorem}
\begin{proof} We need only to prove that $D_b$ satisfies the triangle inequality
$$D_b(\mu,\nu) + D_b(\nu,\omega) \geq D_b(\mu,\omega).$$
By Theorem~\ref{thm:metric}, we have $\mu\sim_{D_b(\mu,\nu)}\nu$ and $\nu\sim_{D_b(\nu,\omega)}\omega$. Then the result follows from Lemma~\ref{lem:abis}(2). \qed
\end{proof}

\subsection{Modal Characterization of the Bisimulation Metrics}
We now present a Hennessy-Milner type modal logic motivated by~\cite{DesharnaisGJP99,DesharnaisGJP04} to characterize the distance between distributions.

\begin{definition} The class $\l_m$ of modal formulae over $AP$, ranged over by $\phi$, $\phi_1$, $\phi_2$, etc, is defined by the following grammar:
\begin{eqnarray*}
%\phi &::=& A \ |\ \phi\oplus p\ |\ \neg \phi\ |\  \bigwedge_{i\in I} \phi_i\ |\ \<a\>\phi
\phi &::=& \B \ |\ \phi\oplus p\ |\ \neg \phi\ |\  \bigwedge_{i\in I} \phi_i\ |\ \<a\>\phi
\end{eqnarray*}
where $\B\subseteq 2^{AP}$, $p\in [0,1]$, $a\in Act$, and $I$ is an index set.
\end{definition}

Given an input enabled probabilistic automaton $\A=(S, Act, \rightarrow,L,\alpha)$ over $AP$,
instead of defining the satisfaction relation $\models$ for the
qualitative setting, the
(discounted) semantics of the logic $\l_m$ is given in terms of
functions from $\dist(S)$ to $[0,1]$.  For any formula $\phi\in \l_m$,
the satisfaction function of $\phi$, denoted by $\phi$ again for
simplicity, is defined in a structural induction way as follows:
\begin{itemize}
\item $\B(\mu) := \sum_{A\in \B}\mu(A)$;
\item $(\phi\oplus p)(\mu) := \min\{\phi(\mu)+p, 1\}$;
\item $(\neg \phi)(\mu) := 1-\phi(\mu)$;
\item $ (\bigwedge_{i\in I} \phi_i)(\mu) := \inf_{i\in I} \phi_{i}(\mu)$;
\item $(\<a\>\phi)(\mu) := \sup_{\TRANA{\mu}{a}{\mu'}} \gamma \cdot\phi(\mu')$.
\end{itemize}



% We remark that, instead of defining the satisfaction relation
% $\models$, our semantics provides a number for each formula. Comparing
% existing interpretations in the literature, we argue that this
% semantics is more robust. For instance in \cite{ParmaS07,HermannsPSWZ11}, a
% distribution $\mu$ satisfies the action $a$, iff all states $s$ in the
% support of $\mu$ satisfy $a$. Another variant \cite{CrafaR11} uses ``there exists a
% state $s$'' instead. Those semantics is neither continuous, nor 
% robust: a small perturbation of the distribution destroys the
% satisfaction answers. We prove that our interpretation has these nice
% properties:

\begin{lemma}\label{lem:continuous}
For any $\phi\in \l_m$, $\phi : \dist(S) \rightarrow [0,1]$ is a continuous function.
\end{lemma}
\begin{proof} We prove by induction on the structure of $\phi$. The basis case when $\phi \equiv \B$ is obvious. The case of $\phi \equiv \phi'\oplus p$, $\phi \equiv \neg \phi'$, and $\phi \equiv \bigwedge_{i\in I} \phi_i$ are all easy from induction.
In the following we only consider the case when $\phi \equiv \<a\>\phi'$. 

Take arbitrarily $\{\mu_i\}_i$ with $\lim_i \mu_i = \mu$. We need to show there exists a subsequence $\{\mu_{i_k}\}_k$ of $\{\mu_i\}_i$ such that $\lim_k\phi(\mu_{i_k}) = \phi(\mu)$. Take arbitrarily $\epsilon >0$. 
\begin{itemize}
\item Let $\mu^*\in \dist(S)$ such that $\TRANA{\mu}{a}{\mu^*}$ and $\phi(\mu)\leq \gamma \cdot\phi'(\mu^*)+\epsilon/2$. We have from the left-convergence of $\TRANA{}{a}{}$ that $\TRANA{\mu_i}{a}{\nu_i}$ for some $\nu_i$, and $\lim_i \nu_i = \mu^*$. By induction, $\phi'$ is a continuous function. Thus we can find $N_1\geq 1$ such that for any $i\geq N_1$, $|\phi'(\mu^*)-\phi'(\nu_i)|<\epsilon/2\gamma$.

\item For each $i\geq 1$, let $\mu_i^*\in \dist(S)$ such that $\TRANA{\mu_i}{a}{\mu_i^*}$ and $\phi(\mu_i)\leq \gamma \cdot\phi'(\mu_i^*)+\epsilon/2$. Then we have $\TRANA{\mu}{a}{\nu^*}$ with $\nu^*=\lim_k \mu_{i_k}^*$ for some convergent subsequence $\{\mu_{i_k}^*\}_k$ of $\{\mu_i^*\}_i$. Again, from the induction that $\phi'$ is continuous, we can find $N_2\geq 1$ such that for any $k\geq N_2$, $|\phi'(\mu_{i_k}^*)-\phi'(\nu^*)|<\epsilon/2\gamma $.
\end{itemize}
Let $N=\max\{N_1, N_2\}$. Then for any $k\geq N$, we have from  $\TRANA{\mu}{a}{\nu^*}$ that
\begin{eqnarray*}
\phi(\mu_{i_k}) - \phi(\mu) &\leq & \gamma [\phi'(\mu_{i_k}^*) -  \phi'(\nu^*)] + \gamma \cdot\phi'(\nu^*) - \phi(\mu) + \epsilon/2\\
&\leq& \gamma [\phi'(\mu_{i_k}^*) -  \phi'(\nu^*)]+ \epsilon/2 < \epsilon.
\end{eqnarray*}
Similarly, from $\TRANA{\mu_{i_k}}{a}{\nu_{i_k}}$ we have
\begin{eqnarray*}
\phi(\mu) - \phi(\mu_{i_k})  &\leq& \gamma [\phi'(\mu^*) - \phi'(\nu_{i_k})] + \gamma \cdot\phi'(\nu_{i_k}) - \phi(\mu_{i_k}) + \epsilon/2 \\
&\leq&\gamma [\phi'(\mu^*) - \phi'(\nu_{i_k})]+ \epsilon/2 < \epsilon.
\end{eqnarray*}
Thus $\lim_k\phi(\mu_{i_k}) = \phi(\mu)$ as required.
\qed
\end{proof}

From Lemma~\ref{lem:continuous}, and noting that the set $\{\mu' \mid
\TRANA{\mu}{a}{\mu'}\}$ is compact for each $\mu$ and $a$, the
supremum in the semantic definition of $\<a\>\phi$ can be replaced by
maximum; that is, $(\<a\>\phi)(\mu) =
\max_{\TRANA{\mu}{a}{\mu'}}\gamma \cdot \phi(\mu')$.
Now we define the logical distance for
distributions.
\begin{definition} The \emph{logic distance} of $\mu$ and $\nu$ in $\dist(S)$ of an input enabled automaton is defined by 
  \begin{align}
    \label{eq:2}
D_l^\A(\mu, \nu) = \sup_{\phi \in \l_m} |\phi(\mu) - \phi(\nu)|\ .    
  \end{align}
The logic distance for a general probabilistic automaton can be
defined in terms of the input enabled extension; that is, $D_l^\A(\mu, \nu) := D_l^{\A_\bot}(\mu, \nu)$. 
We always omit the superscripts for simplicity.
\end{definition}

Now we can show that the logic distance exactly coincides with bisimulation distance for any distributions.

\begin{theorem}\label{thm:dbdl}
$D_b = D_l$. 
\end{theorem}
\begin{proof}
As both $D_b$ and $D_l$ are defined in terms of the input enabled extension of automata, we only need to prove the result for
input enabled case.
Let $\mu, \nu\in \dist(S)$. We first prove $D_b(\mu, \nu) \geq D_l(\mu, \nu)$. It suffices to show by structural induction that for any $\phi\in \l_m$, 
$|\phi(\mu) - \phi(\nu)|\leq D_b(\mu, \nu).$
There are five cases to consider.
\begin{itemize}
\item $\phi \equiv \B$ for some $\B\subseteq 2^{AP}$. Then $|\phi(\mu) - \phi(\nu)| = |\sum_{A\in \B} [\mu(A) -\nu(A)]|
 \leq d_{AP}(\mu, \nu) \leq D_b(\mu, \nu)$ by Theorem~\ref{thm:metric}.
\item $\phi \equiv  \phi'\oplus p$. Assume $\phi'(\mu)\geq \phi'(\nu)$. Then $\phi(\mu)\geq \phi(\nu)$. By induction, we have $\phi'(\mu) - \phi'(\nu)\leq  D_b(\mu, \nu)$.
Thus
$$|\phi(\mu) - \phi(\nu)| = \min\{\phi'(\mu)+p, 1\} -  \min\{\phi'(\nu)+p, 1\}\leq  \phi'(\mu) - \phi'(\nu) \leq  D_b(\mu, \nu).$$

\item $\phi \equiv \neg \phi'$. By induction, we have $|\phi'(\mu) - \phi'(\nu)|\leq  D_b(\mu, \nu)$, thus
$|\phi(\mu) - \phi(\nu)|  = |1- \phi'(\mu) - 1 + \phi'(\nu)| \leq  D_b(\mu, \nu)$ as well.

\item $\phi \equiv   \bigwedge_{i\in I} \phi_i$. Assume $\phi(\mu)\geq  \phi(\nu)$. For any $\epsilon>0$, let $j\in I$ such that $\phi_j(\nu) \leq \phi(\nu)+\epsilon$. By induction, we have $|\phi_j(\mu) - \phi_j(\nu)|\leq  D_b(\mu, \nu)$. Then
$$|\phi(\mu) - \phi(\nu)|  \leq  \phi_{j}(\mu) - \phi_{j}(\nu) +\epsilon \leq  D_b(\mu, \nu) +\epsilon,$$
and $|\phi(\mu) - \phi(\nu)|  \leq D_b(\mu, \nu)$ from the arbitrariness of $\epsilon$.

\item $\phi \equiv \<a\>\phi'$. Assume $\phi(\mu)\geq \phi(\nu)$. 
Let $\mu'_*\in \dist(S)$ such that $\TRANA{\mu}{a}{\mu'_*}$ and $\gamma \cdot\phi'(\mu'_*) = \phi(\mu)$. From Theorem~\ref{thm:metric}, we have 
$\mu\sim_{D_b(\mu, \nu)}\nu$. Thus there exists $\nu'_*$ such that $\TRANA{\nu}{a}{\nu'_*}$ and $\mu'_*\sim_{D_b(\mu, \nu)/\gamma}\nu'_*$. Hence $\gamma \cdot D_b(\mu'_*, \nu'_*) \leq D_b(\mu, \nu)$, and
$$|\phi(\mu) - \phi(\nu)|  \leq  \gamma \cdot[\phi'(\mu'_*) - \phi'(\nu'_*)]\leq  \gamma \cdot D_b(\mu'_*, \nu'_*) \leq  D_b(\mu, \nu)$$
where the second inequality is from induction.
\end{itemize}

Now we turn to the proof of $D_b(\mu, \nu) \leq D_l(\mu, \nu)$. We
will achieve this by showing that the symmetric relations
$R_\epsilon=\{(\mu,\nu) \mid D_l(\mu, \nu) \leq \epsilon \},$ where $\epsilon\geq 0$, constitute an approximate bisimulation. Let $\mu R_\epsilon \nu$ for some $\epsilon \geq 0$. First, for any $\B\subseteq 2^{AP}$ we have 
$$\left|\sum_{A\in \B} \mu(A) - \sum_{A\in \B} \nu(A)\right| = |\B(\mu) - \B(\nu)| \leq D_l(\mu, \nu)\leq \epsilon.$$ 
Thus $d_{AP}(\mu, \nu) \leq \epsilon$ as well.
Now suppose $\TRANA{\mu}{a}{\mu'}$ for some $\mu'$. 
We have to show that there is some $\nu'$ with  $\TRANA{\nu}{a}{\nu'}$ and $D_l(\mu', \nu')\leq \epsilon/\gamma$. Consider the set
$$\k = \{\omega\in \dist(S) \mid \TRANA{\nu}{a}{\omega} \mbox{ and } D_l(\mu', \omega)> \epsilon/\gamma\}.$$
For each $\omega\in \k$, there must be some $\phi_{\omega}$ such that $|\phi_{\omega}(\mu') - \phi_{\omega}(\omega)|> \epsilon/\gamma$. 
As our logic includes the operator $\neg$, we can always assume that $\phi_{\omega}(\mu') > \phi_{\omega}(\omega)+\epsilon/\gamma$.
Let $p= \sup_{\omega\in \k} \phi_{\omega}(\mu')$. Let
$$\phi_{\omega}'=\phi_{\omega} \oplus [p - \phi_{\omega}(\mu')], \ \ \ \phi' = \bigwedge_{\omega\in \k} \phi'_{\omega},\ \ \  \mbox{  and  }\ \ \  \phi = \<a\>\phi'.$$
Then from the assumption that $D_l(\mu, \nu) \leq \epsilon$, we have $|\phi(\mu) - \phi(\nu)| \leq \epsilon$. Furthermore, we check that for any $\omega\in \k$,
$$\phi'_\omega(\mu')=\phi_{\omega}(\mu') \oplus [p - \phi_{\omega}(\mu')]=p.$$
Thus $\phi(\mu) \geq \gamma\cdot\phi'(\mu')=\gamma\cdot p$.

Let 
$\nu'$ be the distribution such that $\TRANA{\nu}{a}{\nu'}$ and $\phi(\nu) =\gamma\cdot \phi'(\nu')$. We are going to show that $\nu'\not\in \k$, and then $D_l(\mu', \nu')\leq \epsilon/\gamma$ as required. For this purpose, assume conversely that $\nu'\in \k$. 
Then
\begin{eqnarray*}
\phi(\nu) &=& \gamma\cdot\phi'(\nu')\leq \gamma\cdot\phi'_{\nu'}(\nu')\leq \gamma\cdot [\phi_{\nu'}(\nu')  +  p - \phi_{\nu'}(\mu')]\\
&<&\gamma\cdot p-\epsilon\leq \phi(\mu)-\epsilon,
\end{eqnarray*}
contradicting the fact that $|\phi(\mu) - \phi(\nu)| \leq \epsilon$. 


We have proven that $\{R_\epsilon \mid \epsilon\geq 0\}$ is an approximate bisimulation. Thus $\mu\sim_\epsilon \nu$, and so $D_b(\mu, \nu) \leq \epsilon$, whenever $D_l(\mu, \nu) \leq \epsilon$. So we have $D_b(\mu, \nu) \leq D_l(\mu, \nu)$ from the arbitrariness of $\epsilon$. 
\qed
\end{proof}


\subsection{A Fixed Point-Based Approach}
In the following, we denote by $\mathcal{M}$ the set of pseudometrics
over $\dist(S)$.  
Denote by $\z$ the zero pseudometric which assigns 0 to each pair of distributions. 
For any $d, d'\in\mathcal{M}$, we write $d\leq d'$
if $d(\mu, \nu)\leq d'(\mu, \nu)$ for any $\mu$ and $\nu$. Obviously
$\leq$ is a partial order, and $(\mathcal{M}, \leq)$ is a complete
lattice.

\begin{definition}\label{def:metricfunc} Let $\A=(S, Act, \rightarrow,L,\alpha)$ be an input enabled probabilistic automaton.  
We define the function $F:\mathcal{M}\to
  \mathcal{M}$ as follows. For any $\mu, \nu\in \dist(S)$, 
%  \begin{eqnarray*}
% F(d)(\mu,\nu) = \max_{a\in Act, A\subseteq AP} &\{& |\mu(A)-\nu(A)|,\\
%&&  \sup_{\TRANA{\mu}{a}{\mu'}} \inf_{\TRANA{\nu}{a}{\nu'}} \gamma\cdot
%  d(\mu',\nu'), \sup_{\TRANA{\nu}{a}{\nu'}}
%  \inf_{\TRANA{\mu}{a}{\mu'}} \gamma\cdot d(\mu',\nu')\}.
%\end{eqnarray*}
  \begin{eqnarray*}
 F(d)(\mu,\nu) = \max_{a\in Act} &\{& d_{AP}(\mu, \nu),\\
&&  \sup_{\TRANA{\mu}{a}{\mu'}} \inf_{\TRANA{\nu}{a}{\nu'}} \gamma\cdot
  d(\mu',\nu'), \sup_{\TRANA{\nu}{a}{\nu'}}
  \inf_{\TRANA{\mu}{a}{\mu'}} \gamma\cdot d(\mu',\nu')\}.
\end{eqnarray*}
Then, $F$ is monotonic
with respect to $\leq$, and by Knaster-Tarski theorem, $F$ has a
least fixed point, denoted $D_f^\A$, given by 
\begin{align*}
D^\A_f = \bigvee_{n=0}^\infty
F^n(\z) \ .  
\end{align*}
\end{definition}

Once again, the fixed point-based distance for a general probabilistic automaton can be
defined in terms of the input enabled extension; that is, $D_f^\A(\mu, \nu) := D_f^{\A_\bot}(\mu, \nu)$. We always omit the superscripts for simplicity.


Similar to
Lemma~\ref{lem:continuous}, we can show that the supremum
(resp. infimum) in Definiton~\ref{def:metricfunc} can be replaced by
maximum (resp. minimum).  
Now  we show
that $D_f$ coincides with $D_b$.
\begin{theorem}\label{thm:dfdb}
$D_f= D_b$.  
\end{theorem}
As both $D_f$ and $D_b$ are defined in terms of the input enabled extension of automata, we only need to prove Theorem~\ref{thm:dfdb} for
input enabled case, which will be obtained by combining Lemma \ref{lem:left} and Lemma \ref{lem:right} below.
\begin{lemma}\label{lem:left}
For input enabled probabilistic automata, $D_f\leq D_b$.
\end{lemma}
\begin{proof}
It suffices to prove by induction that for any $n\geq 0$, $F^n(\z)\leq D_b$. The case of $n=0$ is trivial. Suppose
$F^n(\z)\leq D_b$ for some $n\geq 0$. Then for any $a\in Act$ and any $\mu, \nu$, we have
\begin{enumerate}
\item[(1)] $d_{AP}(\mu, \nu) \leq D_b(\mu, \nu)$ by the fact that $\mu\sim_{D_b(\mu, \nu)} \nu$;
\item[(2)] Note that $\mu\sim_{D_b(\mu, \nu)} \nu$. Whenever $\TRANA{\mu}{a}{\mu'}$, we have $\TRANA{\nu}{a}{\nu'}$ for some $\nu'$ such that $\mu'\sim_{D_b(\mu, \nu)/\gamma} \nu'$, and hence $\gamma\cdot D_b(\mu', \nu')\leq D_b(\mu, \nu)$. That, together with the assumption $F^n(\z)
